use rig::providers::openai::{self, OpenAI};


let model = OpenAI::from_env()?.completion(openai::GPT_5_5).erase();
let writer = AgentBuilder::new(model.clone()).preamble("Draft a one-line tagline.").build();
let editor = AgentBuilder::new(model).preamble("Tighten the tagline to under six words.").build();

let draft = writer.prompt("A tool that compile-checks docs code samples").await?.output();
let tagline = editor.prompt(draft.trim()).await?.output();
println!("{tagline}");

#[derive(Deserialize, schemars::JsonSchema)]
enum Category {
    Code,
    Math,
    Other,
}


let router = AgentBuilder::new(client.completion(openai::GPT_5_MINI))
    .preamble("Classify the user's request.")
    .build();


let query = "How do I borrow a value mutably twice?";
let category = router.prompt_typed::<Category>(query).await?.output;


let answer = match category {
    Category::Code => coder.prompt(query).await?,
    Category::Math => mathematician.prompt(query).await?,
    Category::Other => generalist.prompt(query).await?,
};
println!("{}", answer.output());

let review = "The new update is blazing fast, but the settings menu is confusing.";


let (sentiment, topic) = futures::join!(
    sentiment_agent.prompt(review).into_future(),
    topic_agent.prompt(review).into_future(),
);


println!("sentiment={}, topic={}", sentiment?.output(), topic?.output());

#[derive(Deserialize, schemars::JsonSchema)]
struct Plan {
    /// One instruction per subtask.
    subtasks: Vec<String>,
}


let orchestrator = AgentBuilder::new(model.clone())
    .preamble("Split the task into 2-4 independent writing subtasks.")
    .build();
let worker = AgentBuilder::new(model.clone())
    .preamble("Complete the writing subtask you are given.")
    .build();
let editor = AgentBuilder::new(model)
    .preamble("Merge the drafts into one coherent text.")
    .build();


let task = "Write a product page for an insulated, plastic-free water bottle.";
let plan = orchestrator.prompt_typed::<Plan>(task).await?.output;


// Run every worker concurrently.
let drafts = futures::future::try_join_all(
    plan.subtasks.iter().map(|subtask| worker.prompt(subtask.as_str()).into_future()),
)
.await?;


let combined = drafts.iter().map(|d| d.output()).collect::<Vec<_>>().join("\n\n");
let page = editor.prompt(combined).await?.output();
println!("{page}");

#[derive(Deserialize, schemars::JsonSchema)]
struct Review {
    approved: bool,
    /// Concrete fixes, empty when approved.
    feedback: String,
}


let critic = AgentBuilder::new(model)
    .preamble("Review the text. Approve it only if it is ready to publish.")
    .build();


let mut draft = writer.prompt("A tool that compile-checks docs code samples").await?.output();


for _ in 0..3 {
    let review = critic.prompt_typed::<Review>(draft.as_str()).await?.output;
    if review.approved {
        break;
    }
    let revision = format!("Revise this text:\n{draft}\n\nAddress this feedback:\n{}", review.feedback);
    draft = writer.prompt(revision).await?.output();
}
println!("{draft}");
